sysauto_script.script:
var grscs = new GlideRecord('x_ndecd_triage_2_0_scs');
grscs.query();
while (grscs.next()) {

    if (grscs.etat_annee == '1' || grscs.etat_annee == '2') {
        // test niveau scolaire
        // sk 74911a0d1b413950d991c882604bcbc3 
        // jk 78911a0d1b413950d991c882604bcbc2
        // 1ere 74911a0d1b413950d991c882604bcb59
        // 2eme 74911a0d1b413950d991c882604bcb5b
        if (grscs.eleve.u_classe == "74911a0d1b413950d991c882604bcbc3" || grscs.eleve.u_classe == "78911a0d1b413950d991c882604bcbc2") {
            grscs.etat_annee = 1;
        } else {
            grscs.etat_annee = 0;
        }


    } else if (grscs.etat_annee == '0') {

        grscs.etat_annee = 10;

    } else {
        grscs.etat_annee = 10;
    }

    if (grscs.nom_ducatrice_scs) {
        var gr = new GlideRecord('sys_user');
        gr.addQuery('sys_id', grscs.nom_ducatrice_scs);
        gr.query();

        if (gr.next()) {
            if (grscs.predecessor != '') {
                grscs.predecessor += '\n';
            }

            var gdt = new GlideDateTime();
            var currentDate = gdt.getLocalDate().toString();

            grscs.predecessor += currentDate + " - Nom éducatrice SCS - " + gr.name;
            grscs.nom_ducatrice_scs = "";
        }
    }

    grscs.update();

}
